    # thickness, extending across the perpendicular dimension. Dots turn 4.
    bars=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==bar]
    for r,c in bars:
        if r==0 or r==h-1:
            # horizontal edge bar: copy its run's columns through the grid
            pass
        elif c==0 or c==w-1:
            pass
    # For each edge run, fill its inward-aligned band until the other edge.
    for edge_row in (0,h-1):
        cols=[c for r,c in bars if r==edge_row]
        if cols:
            for r in range(h):
                for c in range(min(cols),max(cols)+1):
                    if g[r][c]==bg:g[r][c]=dot
    for edge_col in (0,w-1):
        rows=[r for r,c in bars if c==edge_col]
        if rows:
            for r in range(min(rows),max(rows)+1):
                for c in range(w):
                    if g[r][c]==bg:g[r][c]=dot
    for r in range(h):
        for c in range(w):
            if grid[r][c]==dot:g[r][c]=4
    return g
